(x, y, t) => {
  const cx = 240, cy = 120;
  const warp1x = Math.sin(x*0.012+t*0.2)*20 + Math.cos(y*0.018-t*0.15)*15;
  const warp1y = Math.cos(y*0.014-t*0.25)*18 + Math.sin(x*0.016+t*0.3)*12;
  const warp2x = Math.sin((x+warp1x)*0.02+t*0.4)*10 + Math.cos((y+warp1y)*0.025-t*0.35)*8;
  const warp2y = Math.cos((y+warp1y)*0.022-t*0.3)*9 + Math.sin((x+warp1x)*0.019+t*0.45)*7;
  const sx = x + warp1x + warp2x, sy = y + warp1y + warp2y;
  const src = [
    [120+Math.sin(t*0.4)*100, 70+Math.cos(t*0.3)*50, 0.07, 2.2, 1.0],
    [360+Math.cos(t*0.5)*90, 80+Math.sin(t*0.6)*60, 0.09, 1.8, 0.8],
    [240+Math.sin(t*0.35+2)*130, 120+Math.cos(t*0.45+1)*80, 0.055, 2.5, 1.2],
    [80+Math.cos(t*0.7+1)*70, 170+Math.sin(t*0.5+3)*55, 0.11, 1.6, 0.7],
    [400+Math.sin(t*0.45+4)*80, 160+Math.cos(t*0.8+2)*65, 0.065, 2.8, 0.9],
    [200+Math.cos(t*0.3+5)*110, 200+Math.sin(t*0.5)*70, 0.085, 2.0, 1.1],
    [300+Math.sin(t*0.55+3)*95, 40+Math.cos(t*0.65+4)*50, 0.1, 1.5, 0.6],
    [160+Math.cos(t*0.38+1.5)*85, 140+Math.sin(t*0.48+2.5)*65, 0.075, 2.3, 1.0]
  ];
  let aS=0, iS=0, aW=0, iW=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const a=Math.sin(d*f-t*sp), i=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    aS+=a*w; iS+=i*w; aW+=Math.abs(a)*w; iW+=Math.abs(i)*w;
  }
  const aN=aS/6.3, iN=iS/6.3, aA=aW/6.3, iA=iW/6.3;
  const bg1=(Math.sin(sx*0.035+sy*0.022+t*0.7)+Math.sin(sx*0.028-sy*0.038+t*0.95))/2;
  const bg2=(Math.sin((sx+sy)*0.11+t*2.2)+Math.sin((sx-sy)*0.095-t*1.8))*0.25;
  const bg3=Math.sin(sx*0.065+t*1.4)*Math.cos(sy*0.055-t*1.1)*0.3;
  const bg=bg1+bg2+bg3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const sp1=Math.sin(dist*0.045-ang*3.5-t*1.3), sp2=Math.sin(dist*0.038+ang*4.5-t*1.0);
  const sp3=Math.sin(dist*0.06-ang*2-t*1.8)*Math.cos(ang*5+t*0.7)*0.5;
  const spiral=(sp1+sp2)*0.35+sp3*0.3;
  const n1=Math.sin(sx*0.13+sy*0.09+t*0.5)*Math.sin(sx*0.11-sy*0.14-t*0.7);
  const n2=Math.sin((sx*0.08+sy*0.12+t*0.9))*Math.cos((sx*0.1-sy*0.07-t*0.6));
  const noise=(n1+n2)*0.35;
  const flow=Math.sin(sx*0.04+Math.sin(sy*0.03+t*0.4)*3+t*0.6)*Math.cos(sy*0.04+Math.cos(sx*0.035-t*0.5)*3-t*0.4)*0.4;
  const reaction=Math.tanh((aN-iN*0.65+bg*0.25+spiral+noise*0.4+flow)*2.0);
  const inhibition=Math.tanh((iA-aA*0.5)*1.5);
  const edge=1.0-Math.min(1,Math.abs(reaction)*3.0)*0.1+Math.min(1,Math.abs(reaction)*1.5)*0.15;
  const glow=Math.max(0,reaction)**2*0.4;
  const cell=Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14)+Math.sin((sx+sy)*0.09+t)*0.4)*1.8)*0.2;
  const micro=Math.sin(sx*0.3+t*2)*Math.sin(sy*0.3-t*1.5)*0.05*(1-Math.abs(reaction));
  const blend=reaction*0.6+cell*0.2+micro+glow*0.15-inhibition*0.08;
  const v=blend*0.5+0.5;
  const pal=[
    [5,12,45],[10,35,75],[15,65,100],[20,105,120],[30,150,130],
    [80,180,120],[160,195,90],[210,190,70],[230,165,75],[225,130,80],
    [200,95,85],[170,65,75],[130,40,65],[85,25,60],[45,18,55],[5,12,45]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const pulse=0.85+Math.sin(reaction*Math.PI)*0.15+glow*0.3;
  const eBoost=1.0+Math.min(1,Math.abs(reaction)*2.5)*0.1;
  const lum=pulse*eBoost;
  return [
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum)|0
  ];
}
